using IndieRun;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static void Wait(Task task){var f=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>f.Continue=false)));Dispatcher.PushFrame(f);task.GetAwaiter().GetResult();}
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Visual(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var v in Visual(VisualTreeHelper.GetChild(root,i)))yield return v;}
    static WorkspaceDocument Plan(string dir)=>new(){SearchRoot=Path.Combine(dir,"input"),SearchLocations=[new(){Path=Path.Combine(dir,"input")}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups")};
    static MainWindow Window(string dir,out Package game)
    {
        var plan=Plan(dir);var path=Path.Combine(plan.SearchRoot,"GeneratedGame");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"generated fixture, never execute");File.WriteAllText(Path.Combine(path,"save.dat"),"preserve this save");
        game=new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=path,DetectedRoot=path,SearchRoot=plan.SearchRoot,Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};plan.Packages.Add(game);var scan=GameScanner.Scan(plan.SearchRoot);scan.PrepareIndex();plan.Checkpoints.Add(WorkspaceReconciler.Capture(game,scan));
        var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());return w;
    }
    [STAThread]static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var rows=new List<object>();int failed=0;
        void Test(string name,Action<string> run){var watch=Stopwatch.StartNew();try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);run(dir);rows.Add(new{name,passed=true,ms=watch.ElapsedMilliseconds});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;rows.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("invalid-primary-validation-recovers-backup",dir=>{var file=Path.Combine(dir,"workspace.json");var store=new WorkspaceStore(file);store.Save(Plan(dir));store.Save(Plan(dir));File.WriteAllText(file,JsonSerializer.Serialize(new WorkspaceDocument()));var got=store.Load();Check(got.Recovered&&got.Document!=null,"InvalidData exception escaped fallback");store.Save(Plan(dir));Check(store.Load().Document!=null&&Directory.GetFiles(dir,"workspace.json.invalid-*").Length==1,"Invalid primary not preserved");});
        Test("invalid-primary-and-backup-do-not-crash",dir=>{var file=Path.Combine(dir,"workspace.json");File.WriteAllText(file,JsonSerializer.Serialize(new WorkspaceDocument()));File.WriteAllText(file+".bak",JsonSerializer.Serialize(new WorkspaceDocument()));var result=new WorkspaceStore(file).Load();Check(result.Document==null&&result.Error!=null,"Invalid metadata accepted");});
        Test("workspace-over-previous-128mb-limit",dir=>{var file=Path.Combine(dir,"workspace.json");using(var stream=File.Create(file)){var json=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(Plan(dir)));stream.Write(json);var space=Enumerable.Repeat((byte)' ',1024*1024).ToArray();for(int i=0;i<129;i++)stream.Write(space);}var store=new WorkspaceStore(file);Check(store.Load().Document!=null,"Large valid workspace refused");store.Save(Plan(dir));Check(store.Load().Document!=null,"Large previous workspace blocked save");});
        Test("over-safe-size-load-reports-error",dir=>{var file=Path.Combine(dir,"workspace.json");using(var output=File.Create(file))output.SetLength(WorkspaceStore.MaxFileBytes+1);var result=new WorkspaceStore(file).Load();Check(result.Document==null&&result.Error!=null,"Oversize exception escaped");});
        Test("shareable-diagnostics-contain-no-filenames",dir=>{foreach(var ex in new Exception[]{new UnauthorizedAccessException("SECRET_GAME"),new InvalidDataException("確認"),new InvalidDataException("확인 기준이 올바르지 않습니다. SECRET_GAME"),new IOException("SECRET_GAME"),new JsonException("SECRET_GAME")}){var issue=WorkspaceSaveIssue.From(ex);Check(!issue.Code.Contains("SECRET")&&!issue.Message.Contains("SECRET"),"Personal detail in shareable code");}Check(WorkspaceSaveIssue.From(new InvalidDataException("확인 기준이 올바르지 않습니다.")).Code=="SAVE-CHECKPOINT","Wrong checkpoint code");});
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        Test("tab-change-clears-organize-hint",dir=>{var w=Window(dir,out _);try{Call(w,"Say","게임을 추가해도 폴더는 이동하지 않습니다.");Call(w,"SetPage","play");Check(((TextBlock)w.FindName("Notice")).Text.Length==0,"Stale hint remains");}finally{Close(w);}});
        Test("register-retains-files-and-offers-transfer",dir=>{var w=Window(dir,out var game);try{Set(w,"identityNoticeAccepted",true);Get<HashSet<string>>(w,"organizeSelection").Add(game.Id);Wait((Task)Call(w,"AddPickedGamesAsync",false)!);Check(game.Registered==true&&Directory.Exists(game.Source),"Registration moved files");Check(((Button)w.FindName("MovePickedButton")).Visibility==Visibility.Visible&&((Button)w.FindName("MovePickedButton")).Content as string=="보관함으로 옮기기","No next transfer action");Check(new BackupEngine(Path.Combine(dir,"backups")).ListJobs().Count==0,"Registration silently started backup");}finally{Close(w);}});
        Test("registered-game-plan-copy-is-not-a-second-registration",dir=>{var w=Window(dir,out var game);try{Check((bool)Call(w,"RegisterGame",game,true)!,"Initial registration failed");var plan=new MoveSelection(new[]{game},Get<List<Package>>(w,"packages"));var draft=plan.Items(Path.Combine(dir,"library")).Single();Check(!ReferenceEquals(game,draft),"Test did not create the real plan copy");Check((bool)Call(w,"RegisterGame",draft,true)!,"Plan copy mistaken for duplicate registration");}finally{Close(w);}});
        Test("same-id-at-a-different-folder-still-refused",dir=>{var w=Window(dir,out var game);try{Check((bool)Call(w,"RegisterGame",game,true)!,"Initial registration failed");var other=JsonSerializer.Deserialize<Package>(JsonSerializer.Serialize(game))!;other.Source=other.DetectedRoot=Path.Combine(game.SearchRoot,"Copy");Directory.CreateDirectory(other.Source);File.Copy(Path.Combine(game.Source,LibraryStore.MarkerName),Path.Combine(other.Source,LibraryStore.MarkerName));var before=File.ReadAllText(Path.Combine(other.Source,LibraryStore.MarkerName));Check(!(bool)Call(w,"RegisterGame",other,true)!,"Real copy collision accepted");Check(File.ReadAllText(Path.Combine(other.Source,LibraryStore.MarkerName))==before&&Directory.Exists(game.Source),"Collision test rewrote identity or source");}finally{Close(w);}});
        Test("different-id-at-the-same-folder-still-refused",dir=>{var w=Window(dir,out var game);try{Check((bool)Call(w,"RegisterGame",game,true)!,"Initial registration failed");var other=JsonSerializer.Deserialize<Package>(JsonSerializer.Serialize(game))!;other.Id=Guid.NewGuid().ToString("N");Check(!(bool)Call(w,"RegisterGame",other,true)!,"Unrelated entry silently merged");Check(LibraryStore.ReadIdentity(game.Source)!.GameId==game.Id,"Existing identity rewritten");}finally{Close(w);}});
        Test("same-entry-compares-normalized-path-and-id",dir=>{var p=new Package{Id=Guid.NewGuid().ToString("N"),Source=Path.Combine(dir,"Game")};var copy=new Package{Id=p.Id.ToUpperInvariant(),Source=p.Source.ToUpperInvariant()+Path.DirectorySeparatorChar};Check(GameRegistration.SameEntry(p,copy),"Canonical path or ID case rejected");copy.Source=Path.Combine(dir,"Game2");Check(!GameRegistration.SameEntry(p,copy),"Sibling folder merged");});
        Test("registered-plan-copy-backs-up-and-moves",dir=>{var w=Window(dir,out var game);var original=game.Source;Window? dialog=null;try{Check((bool)Call(w,"RegisterGame",game,true)!,"Initial registration failed");Check((bool)Call(w,"FlushWorkspace")!,"Initial save failed");dialog=(Window)Call(w,"BuildMovePlan",new List<Package>{game},Path.Combine(dir,"library"))!;var session=Get<MoveSelection>(w,"pendingMovePlan");session.Available.Single().Name="ChosenFolder";var plan=session.Items(Path.Combine(dir,"library"));Check(!ReferenceEquals(plan.Single(),game),"Real plan copy not used");dialog.Close();dialog=null;Wait((Task)Call(w,"ExecuteMoveListAsync",plan,Path.Combine(dir,"library"))!);var target=Path.Combine(dir,"library","ChosenFolder");var engine=new BackupEngine(Path.Combine(dir,"backups"));Check(!Directory.Exists(original)&&File.ReadAllText(Path.Combine(target,"save.dat"))=="preserve this save","Registered plan did not move files intact");Check(engine.ListJobs().Single().Status=="Completed"&&engine.ListMoves().Single().Status=="Completed","Backup/move not completed");Check(LibraryStore.ReadIdentity(target)!.GameId==game.Id&&game.Source==target&&game.Alias=="가상 게임","Identity, alias or live location lost");}finally{dialog?.Close();Close(w);}});
        Test("backup-only-through-mainwindow-creates-verified-job",dir=>{var w=Window(dir,out var game);try{Wait((Task)Call(w,"StartBackupBatchAsync",new List<Package>{game})!);var engine=new BackupEngine(Path.Combine(dir,"backups"));var job=engine.ListJobs().Single();Check(job.Status=="Completed"&&job.SourceVerified&&Directory.Exists(game.Source),"Backup did not complete or moved source");Check(job.Files.Any(f=>f.RelativePath=="save.dat"),"Save omitted");}finally{Close(w);}});
        Test("backup-and-move-through-mainwindow-moves-real-fixture",dir=>{var w=Window(dir,out var game);var original=game.Source;try{Wait((Task)Call(w,"ExecuteMoveListAsync",new List<Package>{game},Path.Combine(dir,"library"))!);var target=Path.Combine(dir,"library","GeneratedGame");var engine=new BackupEngine(Path.Combine(dir,"backups"));Check(!Directory.Exists(original)&&File.ReadAllText(Path.Combine(target,"save.dat"))=="preserve this save","Files did not move intact");Check(engine.ListJobs().Single().Status=="Completed"&&engine.ListMoves().Single().Status=="Completed","Missing completed backup/move");Check(new WorkspaceStore(Path.Combine(dir,"data","workspace.json")).Load().Document!.Packages.Single().Source==target,"Saved path not updated");}finally{Close(w);}});
        Test("cached-selection-verifies-only-selected-folder",dir=>{var w=Window(dir,out var game);try{game.ReviewState="cached";Set(w,"snapshot",null);Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(dir,"never-search-this")}});Wait((Task)Call(w,"VerifyTransferSelectionAsync",new List<Package>{game})!);Check(game.ReviewState.Length==0&&Get<ScanSnapshot>(w,"snapshot").ContainsDirectory(game.Source),"Cached game could not prepare transfer");}finally{Close(w);}});
        Test("partial-verification-does-not-mark-other-games-missing",dir=>{var w=Window(dir,out var game);try{LibraryStore.EnsureIdentity(game.Source,game.Id);var scan=GameScanner.Scan(game.SearchRoot);Set(w,"checkpoints",new List<FolderCheckpoint>{WorkspaceReconciler.Capture(game,scan)});var other=Guid.NewGuid().ToString("N");var store=new LibraryStore(Path.Combine(dir,"library"));store.Update(doc=>{doc.Games.Add(new(){Id=game.Id,Folder=game.Name,LastKnownPath=game.Source,Status="External"});doc.Games.Add(new(){Id=other,Folder="Other",LastKnownPath=Path.Combine(dir,"other"),Status="Present"});});Set(w,"libraryDocument",store.Load());Set(w,"snapshot",null);game.ReviewState="cached";Wait((Task)Call(w,"VerifyTransferSelectionAsync",new List<Package>{game})!);Check((bool)Call(w,"FlushWorkspace")!,"Save failed");Check(store.Load().Games.Single(g=>g.Id==other).Status=="Present","Unscanned game incorrectly marked missing");}finally{Close(w);}});
        Test("save-error-has-private-details-only-in-expander",dir=>{var w=Window(dir,out var game);try{var baseline=Get<List<FolderCheckpoint>>(w,"checkpoints").Single();baseline.Source=Path.Combine(dir,"wrong");Check(!(bool)Call(w,"FlushWorkspace")!,"Invalid checkpoint saved");Check(Get<WorkspaceSaveIssue>(w,"workspaceSaveIssue").Code=="SAVE-CHECKPOINT","Failure has no useful code");}finally{Close(w);}});
        Test("transfer-dialog-layout-and-actions",dir=>{var w=Window(dir,out var game);Window? dialog=null;try{dialog=(Window)Call(w,"BuildMovePlan",new List<Package>{game},Path.Combine(dir,"library"))!;var body=(FrameworkElement)dialog.Content;body.Measure(new Size(840,720));body.Arrange(new Rect(0,0,840,720));body.UpdateLayout();var buttons=Visual(body).OfType<Button>().ToList();Check(buttons.Any(b=>b.Content as string=="보관함으로 옮기기")&&buttons.Any(b=>b.Content as string=="보관함으로 옮기기"),"Missing physical operation actions");Check(buttons.All(b=>b.ActualWidth<1||b.TranslatePoint(new Point(),body).X+b.ActualWidth<=840+1),"Action clipped");var bitmap=new RenderTargetBitmap(840,720,96,96,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var drawing=background.RenderOpen())drawing.DrawRectangle((Brush)Application.Current.FindResource("Surface.Primary"),null,new Rect(0,0,840,720));bitmap.Render(background);bitmap.Render(body);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(Path.Combine(dir,"transfer-fixture.png"));encoder.Save(output);}finally{dialog?.Close();Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=rows.Count,passed=rows.Count-failed,failed,results=rows},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
